spec.expr:
sum by (state) (
  increase(navire_delivery_attempts_total{
    component="core",
    job=~"$navire_job",
    instance=~"$navire_instance",
    state=~"success|failure"
  }[$__range])
)

100 *
(sum(
  increase(navire_delivery_attempts_total{
    component="core",
    job=~"$navire_job",
    instance=~"$navire_instance",
    state="failure"
  }[$__range])
) or vector(0))
/
clamp_min(
  sum(
    increase(navire_delivery_attempts_total{
      component="core",
      job=~"$navire_job",
      instance=~"$navire_instance",
      state=~"success|failure"
    }[$__range])
  ),
  1
)

1000 *
sum(
  increase(
    navire_delivery_duration_seconds_sum{
      job=~"$navire_job",
    instance=~"$navire_instance"
    }[$__range]
  )
)
/
clamp_min(
  sum(
    increase(
      navire_delivery_duration_seconds_count{
        job=~"$navire_job",
    instance=~"$navire_instance"
      }[$__range]
    )
  ),
  1
)

1000 *
sum by (provider) (
    increase(
        navire_delivery_duration_seconds_sum{
        job=~"$navire_job",
    instance=~"$navire_instance"
        }[$__range]
    )
    )
    /
    clamp_min(
    sum by (provider) (
        increase(
        navire_delivery_duration_seconds_count{
            job=~"$navire_job",
    instance=~"$navire_instance"
        }[$__range]
        )
    ),
    1
)

sum by (provider, state) (
increase(navire_delivery_attempts_total{
    job=~"$navire_job",
    instance=~"$navire_instance"
}[$__range])
)
